INSERT INTO `tbl_game_community` VALUES (1,'2025-02-17',NULL,'바퀴벌레포커 언제 나오나요',1,11),(4,'2025-02-20',NULL,'하이 ㅋㅋ\n',3,8),(6,'2025-02-20',NULL,'지금 캐치마인드 ㄱㄱ',3,11),(10,'2025-02-20',NULL,'그림 좀 잘 그려봐라',3,38),(11,'2025-02-20',NULL,'진짜 어렵네요 이거',2,38),(12,'2025-02-20',NULL,'저도 바포하고 싶어요',1,38),(13,'2025-02-20',NULL,'캐치마인드는 사람 많네',3,41),(14,'2025-02-20',NULL,'마블 처음하는 사람이 있다고?',2,41),(15,'2025-02-20',NULL,'이게 갓겜이지 ㅋㅋ',3,42),(16,'2025-02-20',NULL,'마블정도면 국민겜 아님?',2,42),(17,'2025-02-20',NULL,'게시판 너무 휑하다',3,43),(18,'2025-02-20',NULL,'싸피마블은 모두 하나?',2,43),(19,'2025-02-20',NULL,'반성좀 해라',3,44),(20,'2025-02-20',NULL,'일단시작 보고있나',2,44),(21,'2025-02-20',NULL,'빨리빨리',3,45),(22,'2025-02-20',NULL,'나만한 마블고수 없지',2,45),(23,'2025-02-20',NULL,'이게 게임이냐',3,46),(24,'2025-02-20',NULL,'방이 없냐',2,46),(25,'2025-02-20',NULL,'요즘 애들은 보겜 귀한줄 몰라',3,47),(26,'2025-02-20',NULL,'근본 모노폴리 어디감',2,47),(27,'2025-02-20',NULL,'이건 진짜 아닌데',3,49),(28,'2025-02-20',NULL,'바포가 끝나야 뭐가 나오지',1,49),(29,'2025-02-20',NULL,'아직도 모노폴리 찾는 틀딱이 있네',2,49),(30,'2025-02-20',NULL,'마피아 추가 기원 1일차',2,50),(31,'2025-02-20',NULL,'여기도 마피아 추가 기원 1일차',3,50),(32,'2025-02-20',NULL,'빨리 바포 추가하고 마피아 해줘',1,50),(33,'2025-02-20',NULL,'마피아 추가 기원 1일차',1,50),(34,'2025-02-20',NULL,'빨리 내줘',1,51),(35,'2025-02-20',NULL,'사사삭',2,51),(36,'2025-02-20',NULL,'사사삭',3,51),(37,'2025-02-20',NULL,'골뱅이',2,52),(38,'2025-02-20',NULL,'나도 금손할래',3,52),(39,'2025-02-20',NULL,'뭐야 왜 바포 없음?',1,52),(40,'2025-02-20',NULL,'크르릉',2,53),(41,'2025-02-20',NULL,'크르르르릉',3,53),(42,'2025-02-20',NULL,'월워뤄워뤄월',1,53),(43,'2025-02-20',NULL,'뭔 뻘글이 이리 많냐',3,54),(44,'2025-02-20',NULL,'아니 여긴 캐치마인드보다 더하네',2,54),(45,'2025-02-20',NULL,'바포기원 1일차는 내꺼',1,54),(46,'2025-02-20',NULL,'93 위 있냐?',3,55),(47,'2025-02-20',NULL,'부루마블은 특딱겜이니까 93 위로도 있겠지?',2,55),(48,'2025-02-20',NULL,'바퀴벌레 포커는 또 뭐야',1,55),(49,'2025-02-20',NULL,'이거 어떻게 맞추는거임',3,56),(50,'2025-02-20',NULL,'식물버전 만들면 할사람?',2,56),(51,'2025-02-20',NULL,'이건 왜 안나옴?',1,56),(52,'2025-02-20',NULL,'왜 여긴 사람 많음? 아닌가?',3,57),(53,'2025-02-20',NULL,'뭐 뻘글세상임 여기?',2,57),(54,'2025-02-20',NULL,'나오지도 않은 게임 커뮤니티가 한페이지를 넘네 ㅋㅋㅋ',1,57),(55,'2025-02-20',NULL,'스물다섯 찾아요',3,58),(56,'2025-02-20',NULL,'여긴 스물다섯 있나?',2,58),(57,'2025-02-20',NULL,'여긴 사람 왜 많음?',1,58),(58,'2025-02-20',NULL,'외쳐 22!!\n외쳐 22!!',3,59),(59,'2025-02-20',NULL,'2등만 22번은 너무해\n2등만 22번은 너무해',2,59),(60,'2025-02-20',NULL,'단어 추가좀 해주세요\n몇판 돌리니까 나온 단어만 보여요\n',3,60),(61,'2025-02-20',NULL,'커스텀 아이디어 추천받아요',2,60),(62,'2025-02-20',NULL,'캐치마인드 하면서 친구가 그린 그림이 너무 충격적이었던 적 있나요? 저는 ‘사자’를 그렸는데 친구가 ‘해바라기’라고 해서 한참 웃었어요. 여러분도 공유해주세요!',3,61),(63,'2025-02-20',NULL,'여러분이 생각하는 부루마블 최고의 땅은 어디인가요? 저는 안드로메다를 좋아하는데, 여러분의 최애 랜드마크는?',2,61),(64,'2025-02-20',NULL,'게임하다 보면 도저히 어떻게 그려야 할지 감이 안 오는 단어들이 있죠. 저는 ‘양심’을 그리려다가 그냥 포기했어요. 여러분은 어떤 단어가 제일 어려웠나요?',3,63),(65,'2025-02-20',NULL,'처음부터 무리하게 호텔 지었다가 파산한 적 있는 사람? ㅋㅋ 여러분이 해봤던 최악의 부루마블 전략 공유해 주세요!',2,63),(66,'2025-02-20',NULL,'그림 실력이 없어도 눈치로 맞히는 사람이 있고, 진짜 예술가처럼 그려도 못 맞히는 경우도 있죠. 여러분은 그림을 잘 그리는 게 중요하다고 생각하나요, 해석력이 더 중요하다고 생각하나요?',3,64),(67,'2025-02-20',NULL,'완전 망할 뻔했다가 기적적으로 역전한 적 있나요? 저는 감옥 갔다가 한 바퀴 쉬면서 친구들이 전부 제 땅 밟고 돈 벌었던 적 있어요. 여러분도 대역전극 경험 있나요?',2,64),(68,'2025-02-20',NULL,'‘물고기’를 그리라고 했더니 친구가 점 하나 찍고 ‘이건 미생물 물고기야’라고 할 때, 정말 던지고 싶었습니다. 여러분도 비슷한 경험 있나요? ㅋㅋㅋ',3,65),(69,'2025-02-20',NULL,'친구한테 땅 팔아달라고 했는데 거절당했을 때, 배신감 장난 아니죠? ㅋㅋ 부루마블 하면서 친구랑 싸울 뻔한 적 있나요?',2,65),(70,'2025-02-20',NULL,'캐치마인드에서 나오면 진짜 그리기 힘든 단어들 중 최악의 단어는? \n예: ‘철학’, ‘공기’, ‘소음’, ‘존재’... \n여러분이 뽑는 최악의 단어는?',3,66),(71,'2025-02-20',NULL,'여러분만의 부루마블 커스텀 룰이 있나요? 예를 들면 ‘파산해도 미션 성공하면 부활’ 같은 규칙! \n재미있는 규칙 있으면 공유해 주세요!',2,66),(72,'2025-02-20',NULL,'캐치마인드에서 ‘양심’ 같은 단어 나오면 멘붕이 오는데, 여러분이라면 어떻게 표현하나요? 기발한 아이디어 공유해주세요!',3,67),(73,'2025-02-20',NULL,'땅 한 칸 차이로 감옥 가거나, 좋은 자리 못 사본 적 있나요? 저는 역세권 땅 사려다가 주사위 1 더 나와서 못 샀어요 ㅠㅠ 여러분의 억울한 순간은?',2,67),(74,'2025-02-20',NULL,'캐치마인드에서 점수 높이려면 빨리 맞히는 게 중요한데, 단어를 연관 지어 생각하는 방법이나 그림에서 중요한 포인트를 보는 노하우 있나요?',3,68),(75,'2025-02-20',NULL,'부루마블 할 때 공격적인 스타일 vs 방어적인 스타일 중 어느 쪽이세요? 저는 무조건 랜드마크부터 사는 공격형 플레이어입니다! 여러분은?',2,68),(76,'2025-02-20',NULL,'친구랑 게임하다가 웃겨서 배 찢어질 뻔한 적 있나요? 저는 친구가 ‘코끼리’를 그렸는데 다들 ‘개미’라고 해서 한참 웃었어요. 여러분도 레전드 에피소드 있으면 공유해주세요!',3,69),(77,'2025-02-20',NULL,'감옥 연속 3번 가기 vs 내 땅에만 아무도 안 밟기 vs 사회복지기금 연속 2번 내기 중 뭐가 제일 짜증 날까요?',2,69);
