  KEY `FKgkq8tfl8qayne0dt8cj98derx` (`game_community_id`),
  KEY `FKkkbrqyy18kkmr9ocjh805o4s6` (`user_id`),
  CONSTRAINT `FKgkq8tfl8qayne0dt8cj98derx` FOREIGN KEY (`game_community_id`) REFERENCES `tbl_game_community` (`game_community_id`),
  CONSTRAINT `FKkkbrqyy18kkmr9ocjh805o4s6` FOREIGN KEY (`user_id`) REFERENCES `tbl_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=147 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
