INSERT INTO `tbl_game_info` VALUES (1,'제품명: 바퀴벌레 포커 (Cockroach Poker)\\n\r\n플레이어 수: 2-4명\\n\r\n연령: 8세 이상\\n\r\n게임 시간: 20-30분\\n\r\n게임 구성품: \\n64장의 동물 카드\\n(바퀴벌레, 파리, 전갈, 쥐, 박쥐, 두꺼비, 거미, 벼룩 각 8장)','https://meeple-file-server-2.s3.ap-northeast-2.amazonaws.com/static-files/Cockroach_Poker_Royal.png','Step 1. 게임 시작\\n\\n\r\n64장의 카드를 모든 플레이어에게 균등하게 나눠줍니다.\\n \r\n각자 받은 카드는 자유롭게 확인할 수 있습니다.\\n\r\n시계 방향으로 게임을 진행하며, 첫 시작 플레이어를 정합니다.\\n\\n\r\nStep 2. 카드 제시\\n\\n\r\n자신의 차례에 한 장의 카드를 선택해 다른 플레이어에게 건네며 카드의 종류를 말합니다.\\n\r\n이때 실제 카드와 다른 종류를 말해도 되는 블러핑이 가능합니다.\\n\\n\r\nStep 3. 판단과 선택\\n\\n\r\n카드를 받은 플레이어는 진실/거짓을 판단하거나, 다른 플레이어에게 넘길 수 있습니다.\\n\r\n정답을 맞추면 제시자가, 틀리면 맞춘 사람이 패배 카드를 받게 됩니다.\\n',1),(2,'제품명: 부루마블 우주여행\\n\r\n플레이어: 2-4명\\n\r\n대상 연령: 8세 이상\\n\r\n게임 시간: 약 60-90분\\n\r\n게임 구성품: \\n\r\n우주 테마의 게임 보드 1개\\n\r\n행성 소유권 카드\\n\r\n우주 정거장/리조트 건설 마커\\n\r\n찬스 카드\\n\r\n우주 크레딧(게임 머니)\\n','https://meeple-file-server-2.s3.ap-northeast-2.amazonaws.com/static-files/BuruMabul.jpg','Step 1. 게임 준비\\n\\n\r\n각 플레이어는 200만 우주 크레딧을 받고 자신의 우주선 말을 선택합니다.\\n \r\n게임의 시작 자금은 초기 행성 구매에 매우 중요합니다.\\n\r\n주사위를 굴려 가장 높은 숫자가 나온 순서대로 게임을 진행하며, 모든 말은 출발점에서 시작합니다.\\n\\n\r\nStep 2. 이동 규칙\\n\\n\r\n자신의 차례에 주사위 2개를 굴려 나온 숫자만큼 시계방향으로 이동합니다.\\n \r\n더블이 나오면 한 번 더 기회가 있지만, 3번 연속은 블랙홀로 이동하는 불이익이 있습니다.\\n\r\n출발점을 지날 때마다 월급 20만 크레딧을 받아 추가 자금을 확보할 수 있습니다.\\n\\n\r\nStep 3. 행동 수행\\n\\n\r\n빈 행성에서는 구매가, 자신의 행성에서는 건설이 가능합니다.\\n \r\n상대방의 행성에 도착하면 정해진 통행료를 지불해야 합니다.\\n\r\n블랙홀이나 우주 정거장 같은 특수 칸에서는 해당하는 특별한 행동을 수행합니다.',2),(3,'제품명: 캐치마인드\\n\r\n플레이어: 2명 이상 (2-4명이 가장 적절)\\n\r\n연령: 6세 이상\\n\r\n게임 시간: 10-20분\\n\r\n게임 구성품:\\n\r\n제시어 카드\\n\r\n점수 기록판\\n\r\n모래시계 또는 타이머 (1분)\\n','https://meeple-file-server-2.s3.ap-northeast-2.amazonaws.com/static-files/CatchMind.jpg','Step 1. 라운드 준비\\n\\n\r\n한 명의 출제자를 정하고, 1분의 제한시간을 설정합니다.\\n\r\n출제자는 제시어 카드를 뽑아 확인하되, 다른 플레이어에게 보여주면 안 됩니다.\\n\\n\r\nStep 2. 그림 그리기\\n\\n\r\n출제자는 제시어를 오직 그림으로만 표현해야 하며, 글자나 숫자는 사용할 수 없습니다.\\n\r\n제스처나 소리를 통한 힌트는 금지되어 있습니다.\\n\\n\r\nStep 3. 정답 맞히기\\n\\n\r\n다른 플레이어들은 자유롭게 답을 외칠 수 있으며, 정답을 맞히면 2점을 얻습니다.\\n\r\n정답자가 나오면 출제자도 1점을 얻지만, 아무도 맞히지 못하면 출제자는 -1점을 받습니다.\\n',3);
/*!40000 ALTER TABLE `tbl_game_info` ENABLE KEYS */;
UNLOCK TABLES;

