INSERT INTO `tbl_game_review` VALUES (1,'너무 재밌어요 굿굿 짱',5,3,4),(2,'굿굿 잡잡',5,3,1),(4,'개꿀잼인데 ㅋㅋ ?',5,3,12),(6,'재밌었어용!!',5,3,7),(8,'마블 모두해',5,2,11),(9,'웹 상에서 즐기는 심리전, 긴장감이 팍팍! 룰이 간단해서 더 재밌게 플레이 할수있었어용.',5,1,1),(10,'우주 공강때 친구들과 온라인으로 즐기는데 시간 가는 줄 모르게 몰입했어요. 자체휴강 할뻔,, ㅋㅎ',4,1,2),(11,'심리전을 펼칠 때 긴장감에 손이 절로 떨리더라고요.',5,1,3),(12,'초기 룰이 조금 까다롭긴 했지만, 게임 플레이 하면서 룰북을 참고할 수 있어서 쉽게 이해할 수 있었습니다.',4,1,4),(13,'카드가 펼쳐질 때마다 웃음 폭발! 온라인 모임 분위기 확 업! 게임이 MZ 스럽고 재밌읍니다.',5,1,5),(14,'너무 재밌어서 시간가는줄 몰랐어요 ㅠㅠ,,. 뭐야, 내 시간 돌려줘요 !',4,1,6),(15,'초보 유저보다는 경험 많은 분들이 하면 재미가 배가 되는 게임입니다.',3,1,7),(16,'블러핑에 실패하면 바로 드러나는 실력이 오히려 웃음을 줍니다.',5,1,8),(17,'몇 판 플레이하자마자 중독되어 머리 쓰는 재미가 쏠쏠하네요.',4,1,9),(18,'상대의 블러핑을 간파하는 순간, 짜릿함이 폭발합니다.',5,1,10),(19,'비슷한 타이틀보다 룰이 단순해 바로 적응할 수 있었어요.',4,1,11),(20,'예상보다 오래 즐길 수 있어 파티용 게임으로도 손색없습니다.',4,1,12),(21,'기괴한 벌레 그래픽이 오히려 몰입도를 높여주는 매력이 있네요.',5,1,13),(22,'플레이하면서 유저들의 성격이 드러나 웃음이 절로 나오더라고요.',5,1,14),(23,'2~3명보다는 4명 이상일 때 진정한 재미가 폭발합니다.',3,1,15),(24,'예상치 못한 상황들이 연속되어 파티 게임으로 딱이에요.',5,1,16),(25,'가볍게 시작했더니 의심과 심리전이 급습해 재밌었어요.',4,1,17),(26,'단순해 보여도 블러핑 전략이 많아 머리를 쓸 수밖에 없네요.',4,1,18),(27,'속임수에 서툴면 금방 들키고 벌칙이 터지니 조심해야 합니다.',3,1,19),(28,'한 판이 짧아 여러 라운드를 즐기기 딱 좋은 웹게임입니다.',5,1,20),(29,'커스텀 기능이 진짜 킥이에요 ㅎㅎㅎ ! 타일을 포켓몬으로 가득채워서 플레이해봤는데 정말 재밌었어요 ㅋㅋㅋ',5,2,1),(30,'블랙홀에 빠진 친구 얼굴 구경하는 재미 !',5,2,2),(31,'어릴 적 추억을 불러일으키는 보드게임, 온라인에서도 여전한 재미를 보여줍니다.',4,2,3),(32,'텔레파시 카드 뽑았을때 UI가 진짜 예쁜거같아요..',3,2,4),(33,'3D, 좋은 그래픽에 몰입감 있었습니다.',5,2,5),(34,'매 라운드마다 전개가 달라 계속 플레이해도 지루할 틈이 없습니다.',4,2,6),(35,'재밌고 낮은 컴퓨터 사양을 요구해서 좋았습니다.',5,2,7),(36,'달 땅가격이 너무 저렴해서 변경해서 플레이 해보고싶었는데, 커스텀 기능덕분에 적용해 볼 수 있었습니다. ㅎㅎㅎ',4,2,8),(37,'룰이 단순해 초보 유저도 쉽게 접근할 수 있는 점이 장점입니다.',4,2,9),(38,'가족 모임에서 온라인으로 즐기니 옛 추억이 새록새록 떠오릅니다.',5,2,10),(39,'내땅에서 통행료 받아낼 때 짜릿합니다 ㅎㅎㅎ!',4,2,12),(40,'학창시절의 추억이 새록새록, 고전의 매력이 여전하네요.',5,2,13),(41,'어릴 적 기억이 떠오르네요. 그땐 사라진 텔레파시 카드 찾느라 방 구석구석 찾아다녔는데. 세상이 참. 좋아졌습니다 !!!',5,2,20),(42,'그냥 서로 얼굴만 봐도 웃긴 게임입니다. ㅋㅋㅋ 최고 !',5,3,1),(43,'대기방에서 테트리스 하는거 좀 재밌었어요 ㅋㅋㅋ 기다리는 순간도 재밌는 MEEPLE 서비스 !',4,3,2),(44,'제시어가 정말 웃겨요 ! ㅋㅋㅋ 모임자리에서 분위기 띄우기 아주 좋습니다 ㅋㅋㅋ',5,3,3),(45,'친구들 얼굴보면서 플레이 하니까 현실감도있고 더 웃긴거 같아요 ㅋㅋㅋ!',4,3,4),(46,'웃음과 수다가 끊이지 않아 즐거운 게임,, 정말 재밌습니다 강추 !',5,3,5),(47,'플레이 할때 욕하는 유저는 벤이 된다니.. 클린해서 좋습니다 ㅎㅎ',5,3,6),(48,'엉뚱한 답변들이 쏟아져 나오면서도 모두가 함께 즐길 수 있는 재미가 있습니다.',4,3,7);
/*!40000 ALTER TABLE `tbl_game_review` ENABLE KEYS */;
UNLOCK TABLES;

